function buildChunkLab() {
  $('#chunks').hidden = true;
  const section = document.createElement('section'); section.id = 'chunk-lab'; section.className = 'story-section section-deep';
  section.innerHTML = `<div class="page-grid"><header class="chunk-heading"><p class="section-label">02 / HOW MACHINES READ TEXT</p><h2>How does a long article become searchable passages?</h2></header><section class="chunk-stage"><div class="chunk-step"><p>A / PREPARE TEXT</p><h3>How does the machine prepare an article?</h3></div><p class="chunk-intro">Before searching an article, the system may need to process its raw text into a cleaner and more usable form.</p><div class="prepare-flow"><article><p class="panel-label">ORIGINAL MARVEL ARTICLE</p><h4 id="raw-title"></h4><div id="raw-article"></div></article><b>→</b><article><p class="panel-label">TEXT PREPROCESSING</p><div class="preprocess-controls"><button data-process="raw" type="button">Raw text</button><button data-process="lower" type="button">Lowercasing</button><button data-process="token" type="button">Tokenization</button><button data-process="stop" type="button">Stopword removal</button></div><p id="process-before"></p><p id="process-after"></p></article><b>→</b><article><p class="panel-label">PROCESSED TEXT</p><div id="prepared-text"></div><p>The prepared text is now ready for the next step: chunking.</p></article></div></section><section class="chunk-stage"><div class="chunk-step"><p>B / CHUNK THE ARTICLE</p><h3>How should we split a long article?</h3></div><p class="chunk-intro">A long article is divided into smaller passages so that the retrieval system can search specific parts instead of treating the entire article as one document.</p><p class="panel-label">ONE ARTICLE, TWO CHUNKING STRATEGIES</p><details class="article-reader"><summary id="article-reader-title"></summary><div id="full-article"></div></details><div class="chunk-tabs" role="tablist"><button data-chunk="sentence" class="is-active" type="button">Sentence-based</button><button data-chunk="paragraph" type="button">Paragraph-based</button></div><div id="chunk-description" class="chunk-description"></div><div id="chunk-cards" class="chunk-cards"></div><div class="strategy-compare"><p class="panel-label">COMPARE THE TWO STRATEGIES</p><div id="strategy-stats"></div></div></section><section class="chunk-stage"><div class="chunk-step"><p>C / RETRIEVE THE EVIDENCE</p><h3>Does chunking change what the machine finds?</h3></div><p class="chunk-intro">The same search query can retrieve different passages depending on how the original article was divided.</p><div class="passage-search"><label>ASK A QUESTION<input id="passage-query" value="What are Machine Man's abilities?"></label><button id="search-passages" class="button" type="button">Search passages</button></div><div class="chunk-tabs retrieval-tabs" role="tablist"><button data-retrieval="sentence" class="is-active" type="button">Sentence-based</button><button data-retrieval="paragraph" type="button">Paragraph-based</button></div><p class="panel-label">RETRIEVED PASSAGES</p><div id="retrieved-passages" class="retrieved-passages"></div><div class="same-query"><p class="panel-label">SAME QUERY, DIFFERENT PASSAGES</p><div id="retrieval-compare"></div><p id="what-changed"></p></div><div class="chunk-summary"><div><strong>1. Passage boundaries</strong><span>Where the article is divided determines what text is stored together.</span></div><div><strong>2. Context</strong><span>Different chunking strategies preserve different amounts of surrounding context.</span></div><div><strong>3. Retrieval results</strong><span>Different passages can lead to different retrieval results for the same query.</span></div><p>Chunking does not decide which answer is correct. It determines how the source text is organized before retrieval.</p></div></section></div>`;
  document.querySelector('#hero-lab').insertAdjacentElement('afterend', section);
  const search = section.querySelector('.passage-search');
  search.innerHTML = `<label>SELECT A QUESTION<select id="passage-query" aria-label="Select a question"><option value="What are Machine Man's abilities?">What are Machine Man's abilities?</option><option value="Who created Machine Man?">Who created Machine Man?</option><option value="How did Machine Man develop his identity?">How did Machine Man develop his identity?</option></select></label><button id="search-passages" class="button" type="button">Search passages</button>`;
  section.querySelector('#retrieved-passages').insertAdjacentHTML('afterend', `<section id="article-answer" class="article-answer" hidden><p class="panel-label">ANSWER FROM THE ARTICLE</p><div id="answer-card"></div></section>`);
  const style = document.createElement('style'); style.textContent = `#chunk-lab .chunk-heading{margin-bottom:38px}#chunk-lab .chunk-heading h2{margin:0;font:var(--module-title)}#chunk-lab .chunk-stage{padding:36px 0 46px;border-bottom:1px solid var(--line)}#chunk-lab .chunk-step{display:flex;align-items:baseline;gap:12px;margin-bottom:12px}#chunk-lab .chunk-step p{margin:0;color:var(--gold);font:500 var(--step-label-size) var(--mono);letter-spacing:.12em}#chunk-lab .chunk-step h3{margin:0;font:500 var(--step-title-size)/1.2 var(--sans)}#chunk-lab .chunk-intro{max-width:760px;margin:0 0 24px;color:var(--muted);font-size:var(--body-font-size)}#chunk-lab .prepare-flow{display:grid;grid-template-columns:1fr 30px 1fr 30px 1fr;gap:12px;align-items:stretch}#chunk-lab .prepare-flow article,#chunk-lab .strategy-compare,#chunk-lab .same-query{border:1px solid var(--line);padding:20px;background:var(--panel)}#chunk-lab .prepare-flow>b{display:grid;place-items:center;color:var(--gold)}#chunk-lab h4{margin:0 0 10px;font:500 27px var(--serif)}#raw-article,#full-article{color:#d2dde0;font-size:14px;line-height:1.75}#raw-article p,#full-article p{margin:0 0 14px}.preprocess-controls{display:flex;flex-wrap:wrap;gap:7px}.preprocess-controls button,.chunk-tabs button{border:1px solid var(--line);padding:8px 10px;background:#091018;color:var(--muted);font:11px var(--mono);text-transform:uppercase}.preprocess-controls button:hover,.preprocess-controls button.is-active,.chunk-tabs button.is-active{border-color:var(--gold);color:var(--gold)}#process-before,#process-after,#prepared-text{white-space:pre-wrap;color:#d2dde0;font:13px/1.65 var(--mono)}#process-after{color:var(--gold)}.article-reader{border:1px solid var(--line);padding:14px;background:#0a1018}.article-reader summary{color:var(--gold);cursor:pointer;font:12px var(--mono)}.article-reader div{max-height:370px;overflow:auto;margin-top:16px}.chunk-tabs{display:flex;gap:8px;margin:18px 0}.chunk-description{color:var(--muted);margin-bottom:16px}.chunk-cards,.retrieved-passages{display:grid;gap:12px}.chunk-card,.retrieved-card{border-left:2px solid #53606a;padding:16px;background:#0a1018}.chunk-card:first-child,.retrieved-card:first-child{border-color:var(--gold)}.chunk-card header,.retrieved-card header{display:flex;justify-content:space-between;gap:10px;color:var(--gold);font:11px var(--mono)}.chunk-card p,.retrieved-card p{max-width:900px;margin:10px 0 0;color:#d2dde0;font-size:14px;line-height:1.7}.strategy-compare{margin-top:16px}.strategy-compare>div,#retrieval-compare{display:grid;grid-template-columns:1fr 1fr;gap:16px}.stat-panel{border:1px solid var(--line);padding:14px}.stat-panel h4{font-size:20px}.stat-panel dl{display:grid;grid-template-columns:1fr 1fr;gap:5px;margin:10px 0;font-size:13px}.stat-panel dt{color:var(--muted)}.stat-panel dd{margin:0;color:var(--gold);font-family:var(--mono)}.passage-search{display:flex;gap:12px;align-items:end;margin-bottom:16px}.passage-search label{flex:1;color:var(--gold);font:11px var(--mono)}.passage-search input{display:block;width:100%;margin-top:7px;border:1px solid var(--line);padding:12px;background:#091018;color:var(--ink);font:15px var(--sans)}#what-changed{margin:16px 0 0;color:var(--muted)}.chunk-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:16px;border-top:1px solid var(--gold);padding-top:18px}.chunk-summary div{display:grid;gap:5px}.chunk-summary strong{color:var(--gold);font:12px var(--mono)}.chunk-summary span,.chunk-summary p{color:var(--muted);font-size:13px}.chunk-summary p{grid-column:1/-1;margin:4px 0 0}@media(max-width:850px){#chunk-lab .prepare-flow{grid-template-columns:1fr}#chunk-lab .prepare-flow>b{transform:rotate(90deg);height:22px}.strategy-compare>div,#retrieval-compare,.chunk-summary{grid-template-columns:1fr}.passage-search{display:grid;align-items:stretch}}`;
  style.textContent += `#chunk-lab .passage-search select{display:block;width:100%;margin-top:7px;appearance:auto;border:1px solid var(--gold);padding:12px;background:#091018;color:var(--ink);font:15px var(--sans)}#chunk-lab .passage-search select:focus{outline:2px solid var(--gold);outline-offset:2px}#chunk-lab .article-answer{margin-top:24px;border:1px solid var(--gold);padding:20px;background:var(--panel)}#chunk-lab .answer-grid{display:grid;gap:18px}#chunk-lab .answer-grid h4{margin:0 0 8px;font:12px var(--mono);color:var(--gold)}#chunk-lab .answer-grid p{margin:0;color:#d2dde0;line-height:1.7}#chunk-lab .answer-evidence{border-left:2px solid var(--gold);padding:14px;background:#0a1018}#chunk-lab .answer-evidence footer{margin-top:10px;color:var(--muted);font:11px var(--mono)}#chunk-lab .answer-pending{padding:16px;border:1px dashed var(--line);color:var(--muted)}#chunk-lab mark{background:var(--gold);color:#071018}`;
  document.head.append(style);
}
function labChunks(strategy) { return strategy === 'sentence' ? state.data.labArticle.sentenceChunks : state.data.labArticle.paragraphChunks; }
function labScore(query, strategy) { const vector = lsaVector(queryVector(query)); return labChunks(strategy).map((chunk) => ({ ...chunk, score: dot(vector, chunk.vector) })).sort((a, b) => b.score - a.score); }
function renderChunkLab(strategy = 'sentence', query = $('#passage-query')?.value || "What are Machine Man's abilities?") { const article = state.data.labArticle; const raw = article.rawParagraphs; $('#raw-title').textContent = article.name; $('#raw-article').innerHTML = raw.slice(0, 3).map((paragraph) => `<p>${paragraph}</p>`).join(''); $('#article-reader-title').textContent = `${article.name} · read the original ${raw.length} paragraphs`; $('#full-article').innerHTML = raw.map((paragraph) => `<p>${paragraph}</p>`).join(''); $('#prepared-text').textContent = article.preparedTokens.join(' · '); document.querySelectorAll('#chunk-lab [data-process]').forEach((button) => { button.onclick = () => { const source = raw[0]; const lower = source.toLowerCase(); const tokenized = (lower.match(/[a-z]{2,}/g) || []).join(' · '); const kept = tokens(source).join(' · '); const view = { raw: source, lower, token: tokenized, stop: kept }[button.dataset.process]; $('#process-before').textContent = `ORIGINAL\n${source}`; $('#process-after').textContent = `AFTER ${button.textContent.toUpperCase()}\n${view}`; document.querySelectorAll('#chunk-lab [data-process]').forEach((item) => item.classList.toggle('is-active', item === button)); }; }); document.querySelector('#chunk-lab [data-process="stop"]').click(); const chunks = labChunks(strategy); $('#chunk-description').textContent = strategy === 'sentence' ? 'Sentences are grouped into passages while keeping sentence boundaries intact. The implemented limit is up to 150 words, not exactly 150 words.' : 'Each original blank-line paragraph becomes a passage. This strategy preserves the source paragraph boundaries without artificial rearrangement.'; $('#chunk-cards').innerHTML = chunks.map((chunk) => `<article class="chunk-card"><header><span>CHUNK ${chunk.id}</span><span>${chunk.words} words</span></header><p>${chunk.text}</p></article>`).join(''); document.querySelectorAll('#chunk-lab [data-chunk]').forEach((button) => { button.classList.toggle('is-active', button.dataset.chunk === strategy); button.onclick = () => renderChunkLab(button.dataset.chunk, query); }); const stat = (name, items) => `<article class="stat-panel"><h4>${name}</h4><dl><dt>Total original words</dt><dd>${raw.join(' ').split(/\s+/).length}</dd><dt>Number of chunks</dt><dd>${items.length}</dd><dt>Average words per chunk</dt><dd>${(items.reduce((sum, item) => sum + item.words, 0) / items.length).toFixed(1)}</dd><dt>Longest chunk</dt><dd>${Math.max(...items.map((item) => item.words))}</dd></dl><p>${items[0].text}</p></article>`; $('#strategy-stats').innerHTML = stat('SENTENCE-BASED', labChunks('sentence')) + stat('PARAGRAPH-BASED', labChunks('paragraph')); renderLabRetrieval(query, strategy); }
function renderLabRetrieval(query, active) { const sentence = labScore(query, 'sentence').slice(0, 3); const paragraph = labScore(query, 'paragraph').slice(0, 3); const render = (items) => items.map((item, index) => `<article class="retrieved-card"><header><span>RANK ${index + 1} · CHUNK ${item.id}</span><span>LSA COSINE ${item.score.toFixed(3)}</span></header><p>${item.text}</p></article>`).join(''); $('#retrieved-passages').innerHTML = render(active === 'sentence' ? sentence : paragraph); $('#retrieval-compare').innerHTML = `<div><p class="panel-label">SENTENCE-BASED RESULTS</p>${render(sentence.slice(0, 1))}</div><div><p class="panel-label">PARAGRAPH-BASED RESULTS</p>${render(paragraph.slice(0, 1))}</div>`; const same = sentence[0].text === paragraph[0].text; $('#what-changed').textContent = same ? `Both strategies retrieved the same relevant passage for this query. Each strategy returned ${sentence.length} displayed results.` : `The chunking strategy changed the passages returned for the same query: sentence-based top chunk ${sentence[0].id} and paragraph-based top chunk ${paragraph[0].id} contain different source text.`; document.querySelectorAll('#chunk-lab [data-retrieval]').forEach((button) => { button.classList.toggle('is-active', button.dataset.retrieval === active); button.onclick = () => renderLabRetrieval($('#passage-query').value, button.dataset.retrieval); }); $('#search-passages').onclick = () => renderLabRetrieval($('#passage-query').value, active); }
function retrievalTerms(query) { return (query.toLowerCase().match(/[a-z]{2,}/g) || []).filter((term) => !['what', 'who', 'how', 'are', 'did', 'his', 'machine', 'man'].includes(term)); }
function rankLabEvidence(query, strategy) { const terms = retrievalTerms(query); const phrase = query === 'Who created Machine Man?' ? 'created by' : ''; return labScore(query, strategy).map((chunk) => ({ ...chunk, matches: terms.filter((term) => chunk.text.toLowerCase().includes(term)).length + (phrase && chunk.text.toLowerCase().includes(phrase) ? 2 : 0) })).sort((first, second) => second.matches - first.matches || second.score - first.score); }
function evidenceMarkup(text, query) { const terms = new Set(retrievalTerms(query)); return text.split(/([A-Za-z]{2,})/).map((piece) => terms.has(piece.toLowerCase()) ? `<mark>${piece}</mark>` : piece).join(''); }
function evidenceSentences(text, query) { const terms = retrievalTerms(query); const sentences = (text.match(/[^.!?]+[.!?]+/g) || [text]).map((sentence) => sentence.trim()); const index = sentences.findIndex((sentence) => terms.some((term) => sentence.toLowerCase().includes(term))); return index < 0 ? [] : sentences.slice(index, index + 3); }
function renderLabRetrieval(query, active, searched = false) {
  const selected = active === 'sentence' ? 'sentence' : 'paragraph';
  const results = rankLabEvidence(query, selected).slice(0, 3);
  const sentence = rankLabEvidence(query, 'sentence').slice(0, 1);
  const paragraph = rankLabEvidence(query, 'paragraph').slice(0, 1);
  const render = (items) => items.map((item, index) => `<article class="retrieved-card"><header><span>RANK ${index + 1} · CHUNK ${item.id}</span><span>LSA COSINE ${item.score.toFixed(3)}</span></header><p>${evidenceMarkup(item.text, query)}</p></article>`).join('');
  const answer = $('#article-answer');
  const bindControls = () => {
    document.querySelectorAll('#chunk-lab [data-retrieval]').forEach((button) => { button.classList.toggle('is-active', button.dataset.retrieval === selected); button.onclick = () => renderLabRetrieval($('#passage-query').value, button.dataset.retrieval, false); });
    $('#passage-query').onchange = () => { const nextQuestion = $('#passage-query').value; if (state.labSearch?.query !== nextQuestion || state.labSearch?.strategy !== selected) renderLabRetrieval(nextQuestion, selected, false); };
    $('#search-passages').onclick = () => { const button = $('#search-passages'); const currentQuestion = $('#passage-query').value; const currentStrategy = document.querySelector('#chunk-lab [data-retrieval].is-active').dataset.retrieval; state.labSearch = { query: currentQuestion, strategy: currentStrategy, status: 'searching' }; button.disabled = true; button.textContent = 'Searching…'; setTimeout(() => { button.disabled = false; button.textContent = 'Search passages'; try { renderLabRetrieval(currentQuestion, currentStrategy, true); } catch (error) { $('#retrieved-passages').innerHTML = `<p class="answer-pending">Retrieval failed: ${error.message}</p>`; answer.hidden = true; } }, 180); };
  };
  if (!searched) { state.labSearch = { query, strategy: selected, status: 'stale' }; $('#retrieved-passages').innerHTML = '<p class="answer-pending">Select a question and choose a chunking strategy, then search the article.</p>'; answer.hidden = true; $('#retrieval-compare').innerHTML = ''; $('#what-changed').textContent = 'Results have not been updated for the current question and chunking strategy.'; bindControls(); return; }
  state.labSearch = { query, strategy: selected, status: 'complete' };
  $('#retrieved-passages').innerHTML = render(results);
  $('#retrieval-compare').innerHTML = `<div><p class="panel-label">SENTENCE-BASED RESULTS</p>${render(sentence)}</div><div><p class="panel-label">PARAGRAPH-BASED RESULTS</p>${render(paragraph)}</div>`;
  const evidence = results.find((item) => item.matches > 0);
  answer.hidden = false;
  if (!evidence) { $('#answer-card').innerHTML = `<div class="answer-grid"><div><h4>SELECTED QUESTION</h4><p>${query}</p></div><div><h4>GENERATED ANSWER</h4><p>No sufficient evidence was found in the retrieved passages to answer this question.</p></div></div>`; }
  else { const sentences = evidenceSentences(evidence.text, query); const generated = sentences.length ? `The retrieved article states that ${sentences[0]}${sentences[1] ? ` It also states that ${sentences[1]}` : ''}` : 'No sufficient evidence was found in the retrieved passages to answer this question.'; $('#answer-card').innerHTML = `<div class="answer-grid"><div><h4>SELECTED QUESTION</h4><p>${query}</p></div><div><h4>GENERATED ANSWER</h4><p>${generated}</p></div><div><h4>SUPPORTING EVIDENCE</h4><div class="answer-evidence"><p>${evidenceMarkup(evidence.text, query)}</p><footer>${state.data.labArticle.name} · CHUNK ${evidence.id} · RANK ${results.indexOf(evidence) + 1} · LSA COSINE ${evidence.score.toFixed(3)}</footer></div></div><div><h4>WHY THIS ANSWER?</h4><p>The highest-ranked passage containing the question's specific terms provides the quoted evidence.</p></div></div>`; }
  const same = sentence[0].text === paragraph[0].text;
  $('#what-changed').textContent = same ? 'Both strategies returned the same highest-ranked evidence for this question.' : `The same question returned different highest-ranked passages: sentence chunk ${sentence[0].id} and paragraph chunk ${paragraph[0].id}.`;
  bindControls();
}
function initialiseChunkLab() { buildChunkLab(); renderChunkLab(); }
function renderHeroInput() { const target = $('#hero-trait-controls'); target.replaceChildren(); state.data.traits.forEach((trait, index) => { const label = document.createElement('label'); label.className = 'interest-choice'; label.innerHTML = `<input type="checkbox" value="${trait.id}" ${index === 0 ? 'checked' : ''}><strong>${trait.label}</strong><span>${heroDescriptions[trait.id]}</span>`; label.querySelector('input').addEventListener('change', () => { const selected = traitsSelected(); $('#hero-query-input').value = selected.map((item) => item.query).join(' '); renderHeroQuery(false); }); target.append(label); }); }
function renderTransform(selected) { $('#selection-count').textContent = `${selected.length} interest${selected.length === 1 ? '' : 's'} selected`; const interests = $('#selected-interests'), mapping = $('#keyword-mapping'), detail = $('#mapping-detail'); interests.replaceChildren(); mapping.replaceChildren(); detail.replaceChildren(); selected.forEach((trait) => { const tag = document.createElement('span'); tag.textContent = trait.label; interests.append(tag); const map = document.createElement('div'); map.innerHTML = `<strong>${trait.label}</strong><em>${trait.query.split(' ').join(' · ')}</em>`; mapping.append(map); const full = document.createElement('div'); full.innerHTML = `<strong>${trait.label}</strong><span>${trait.query.split(' ').join(' · ')}</span>`; detail.append(full); }); }
function renderComparison(card, result) { card.innerHTML = `<output>${result.query}</output><ol>${result.ranks.map((rank, index) => `<li><span>0${index + 1} ${state.data.documents[rank.index].name}</span><b>${rank.score.toFixed(3)}</b></li>`).join('')}</ol>`; }
function wikiImage(documentIndex) { const image = $('#winner-image'); const id = state.data.documents[documentIndex].id; fetch(`https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(id)}`).then((response) => response.ok ? response.json() : null).then((data) => { if (data?.thumbnail?.source) { image.src = data.thumbnail.source; image.alt = `${state.data.documents[documentIndex].name} Wikipedia image`; } }).catch(() => {}); }
function renderHeroResults() { const ranking = rankDocuments(state.vector, 'lsa'); const winner = ranking[0]; const winnerPassage = rankedPassages(winner.index)[0]; $('#winner-name').textContent = state.data.documents[winner.index].name; $('#winner-score').textContent = winner.score.toFixed(3); const snippet = $('#winner-snippet'); snippet.replaceChildren(); highlight(snippet, winnerPassage?.passage.text.slice(0, 370) || 'No passage available.'); wikiImage(winner.index); $('#hero-ranking').innerHTML = ranking.slice(1, 3).map((item, index) => `<li><span>0${index + 2}</span><strong>${state.data.documents[item.index].name}</strong><b>${item.score.toFixed(3)}</b></li>`).join(''); const articles = ranking.slice(0, 2); $('#vector-query').textContent = state.query; $('#vector-articles').innerHTML = articles.map((item, index) => { const passage = rankedPassages(item.index)[0]; return `<div><strong>${index === 0 ? 'A' : 'B'} · ${state.data.documents[item.index].name} <em>${item.score.toFixed(3)}</em></strong><p>${passage?.passage.text.slice(0, 130) || ''}…</p></div>`; }).join(''); $('#vector-cosine').textContent = `Q ↔ A = ${winner.score.toFixed(3)}`; $('#score-title').textContent = `WHAT DOES ${winner.score.toFixed(3)} MEAN?`; $('#score-big').textContent = winner.score.toFixed(3); $('#score-explanation').textContent = `This is the cosine similarity between the query vector and the ${state.data.documents[winner.index].name} article vector in the current LSA representation.`; $('#score-scale').innerHTML = ranking.slice(0, 3).map((item) => `<div><span>${state.data.documents[item.index].name}</span><i style="height:${Math.max(8, item.score / winner.score * 42)}px"></i><b>${item.score.toFixed(3)}</b></div>`).join(''); const evidence = $('#hero-evidence'); const queryTags = $('#evidence-query-tags'); queryTags.innerHTML = tokens(state.query).map((term) => `<span>${term}</span>`).join(''); const evidenceText = $('#evidence-text'); evidenceText.replaceChildren(); highlight(evidenceText, winnerPassage?.passage.text || ''); const evidenceTerms = contributions(winner.index); $('#evidence-chips').innerHTML = evidenceTerms.length ? evidenceTerms.slice(0, 5).map((item) => `<span>${item.term} ${item.value.toFixed(3)}</span>`).join('') : '<span>No exact query terms contribute to this article’s sparse score.</span>'; $('#evidence-why').textContent = evidenceTerms.length ? 'The highlighted terms occur in both the query and this article; the chips show their exact TF-IDF contribution. The final LSA score also reflects low-rank combinations of TF-IDF patterns.' : 'This result has no exact query-term overlap in the retained sparse vocabulary. Its score comes from the low-rank LSA representation, so the passage must be read as evidence rather than a word-level explanation.'; $('#evidence-toggle').onclick = () => { evidence.hidden = !evidence.hidden; $('#evidence-toggle').setAttribute('aria-expanded', String(!evidence.hidden)); }; renderComparison($('#modified-search'), snapshot()); if (!state.baseline) { state.baseline = snapshot(); renderComparison($('#original-search'), state.baseline); } }
function renderMachineComparison() { const winner = rankDocuments(state.vector, 'lsa')[0]; const passage = rankedPassages(winner.index)[0]; $('#machine-query').textContent = state.query; $('#vector-articles').innerHTML = `<div><strong>${state.data.documents[winner.index].name}</strong><p>${passage?.passage.text.slice(0, 420) || ''}</p></div>`; }
function renderHeroQuery(keepBaseline) { const selected = traitsSelected(); const query = $('#hero-query-input').value.trim(); const vector = queryVector(query); if (!query || !vector.some(Boolean)) return; state.query = query; state.vector = vector; $('#hero-query').textContent = query; renderTransform(selected); renderHeroResults(); renderMachineComparison(); if (!keepBaseline) renderComparison($('#modified-search'), snapshot()); }
function buildHeroLab() { injectHeroLab(); renderHeroInput(); const input = document.createElement('input'); input.id = 'hero-query-input'; input.type = 'text'; input.value = state.data.traits[0].query; input.setAttribute('aria-label', 'Final search query'); input.style.cssText = 'display:block;width:100%;margin-bottom:10px;border:1px solid #ffd25a;padding:12px;background:#080e15;color:#fff4c4;font:14px/1.5 DM Mono,monospace'; $('#hero-query').before(input); input.addEventListener('input', () => renderHeroQuery(false)); $('#update-search').addEventListener('click', () => { renderHeroQuery(false); runLegacy(); }); $('#mapping-toggle').addEventListener('click', () => { const detail = $('#mapping-detail'); detail.hidden = !detail.hidden; $('#mapping-toggle').setAttribute('aria-expanded', String(!detail.hidden)); $('#mapping-toggle').innerHTML = `${detail.hidden ? 'View' : 'Hide'} keyword mapping <span>${detail.hidden ? '↓' : '↑'}</span>`; }); renderHeroQuery(true); }

function renderWeights() { const list = $('#weight-list'); list.replaceChildren(); const terms = [...state.vector].map((weight, index) => ({ term: state.data.vocabulary[index], weight })).filter((item) => item.weight).sort((first, second) => second.weight - first.weight); terms.forEach(({ term, weight }) => { const row = document.createElement('div'); row.innerHTML = `<span>${term}</span><i><b style="width:${weight / terms[0].weight * 100}%"></b></i><strong>${weight.toFixed(3)}</strong>`; list.append(row); }); }
function renderPassages() { const list = $('#passage-list'); list.replaceChildren(); rankedPassages().slice(0, 3).forEach(({ passage, score }) => { const card = document.createElement('article'); card.className = 'passage'; const copy = document.createElement('p'); highlight(copy, passage.text); card.innerHTML = `<span>Passage ${passage.index + 1} · LSA cosine ${score.toFixed(3)}</span><h3>${state.data.documents[passage.document].name}</h3>`; card.append(copy); list.append(card); }); $('#chunk-note').textContent = state.chunking === 'first' ? 'Each article contributes its first 180 words. This tests a truncation-style rule.' : 'Each article is split at sentence boundaries into passages of at most 150 words.'; }
function renderResults(results, target) { const list = $(target); list.replaceChildren(...results.slice(0, 3).map(({ index, score }, rank) => { const item = document.createElement('li'); item.innerHTML = `<button type="button"><span>0${rank + 1}</span><strong>${state.data.documents[index].name}</strong><b>${score.toFixed(3)}</b></button>`; return item; })); }
function renderChallenge(sparse, lsa) { if (!$('#challenge-style')) { const style = document.createElement('style'); style.id = 'challenge-style'; style.textContent = `#challenge .challenge-heading{margin:0 0 58px}#challenge .challenge-heading h2{margin:0;font:var(--module-title)}#challenge .challenge-heading p{margin:12px 0 0;color:var(--muted);font:17px/1.5 var(--sans)}#challenge .challenge-step{padding:36px 0 42px;border-bottom:1px solid var(--line)}#challenge .challenge-step-label{margin:0 0 9px;color:var(--gold);font:500 11px var(--mono);letter-spacing:.12em}#challenge .challenge-step h3{margin:0;font:500 var(--step-title-size)/1.2 var(--sans)}#challenge .challenge-query-note{margin:14px 0 8px;color:var(--gold);font:12px var(--mono)}#challenge .challenge-query{display:block;width:100%;border:1px solid var(--line);padding:16px;background:#0a1018;color:var(--ink);font:14px/1.6 var(--mono)}#challenge .challenge-methods{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:20px}#challenge .challenge-methods article{border:1px solid var(--line);padding:20px;background:var(--panel)}#challenge .challenge-methods article>p:not(.panel-label){min-height:50px;margin:0;color:var(--muted);font-size:14px}#challenge .challenge-results{margin:18px 0 0;padding:0;list-style:none}#challenge .challenge-results li{border-top:1px solid var(--line)}#challenge .challenge-results button{display:grid;width:100%;grid-template-columns:34px 1fr auto;gap:10px;align-items:center;border:0;padding:12px 0;background:transparent;color:var(--ink);text-align:left}#challenge .challenge-results li:first-child button{color:var(--gold)}#challenge .challenge-results span,#challenge .challenge-results b{font:12px var(--mono)}#challenge .challenge-score-note{margin:18px 0 0;color:var(--muted);font-size:14px}#challenge .challenge-score-note small{display:block;margin-top:5px;font:12px var(--mono)}#challenge .challenge-summary{display:grid;gap:10px;margin-top:18px}#challenge .challenge-summary p{margin:0;border-left:2px solid var(--gold);padding:10px 14px;background:#0a1018;color:var(--muted)}#challenge .challenge-summary strong{display:block;color:var(--ink);font:12px var(--mono)}@media(max-width:720px){#challenge .challenge-heading{margin-bottom:42px}#challenge .challenge-methods{grid-template-columns:1fr}}`; document.head.append(style); } const sparseNames = sparse.slice(0, 3).map((item) => state.data.documents[item.index].name); const lsaNames = lsa.slice(0, 3).map((item) => state.data.documents[item.index].name); const top = sparseNames[0] === lsaNames[0] ? `Both methods ranked ${sparseNames[0]} first.` : `The top-ranked character changed: TF-IDF ranked ${sparseNames[0]} first, while LSA ranked ${lsaNames[0]} first.`; const lower = sparseNames.slice(1).every((name, index) => name === lsaNames[index + 1]) ? 'The second and third positions stayed the same.' : `The lower rankings changed: TF-IDF returned ${sparseNames[1]} and ${sparseNames[2]}, while LSA returned ${lsaNames[1]} and ${lsaNames[2]}.`; const scores = sparse.slice(0, 3).some((item, index) => item.score.toFixed(3) !== lsa[index].score.toFixed(3)) ? 'The similarity scores changed because each method compares vectors in a different representation space.' : 'The displayed similarity scores did not change for these top results.'; $('#challenge-query').textContent = state.query; $('#challenge-summary').innerHTML = `<p><strong>1. Top-ranked character</strong>${top}</p><p><strong>2. Second and third positions</strong>${lower}</p><p><strong>3. Similarity scores</strong>${scores}</p>`; }
function renderConcept(key) { const [title, body, note] = concepts[key]; $('#concept-panel').innerHTML = `<div><h3>${title}</h3><p>${body}</p><p class="concept-note">${note}</p></div><div class="vector-diagram"><span>text</span><b>→</b><span>numbers</span><b>→</b><span>cosine rank</span></div>`; }
function runLegacy() { const sparse = rankDocuments(state.vector, 'sparse'); const lsa = rankDocuments(state.vector, 'lsa'); renderResults(sparse, '#sparse-results'); renderResults(lsa, '#lsa-results'); renderChallenge(sparse, lsa); renderPassages(); renderWeights(); $('#match-name').textContent = state.data.documents[lsa[0].index].name; $('#match-score').textContent = lsa[0].score.toFixed(3); $('#match-copy').textContent = `Cosine similarity in the 48-dimensional low-rank LSA representation for “${state.query}”.`; $('#lab-status').textContent = `Compared against ${state.data.meta.documents} frozen course articles using the same query.`; }
async function initialise() { try { const response = await fetch('data/processed/retrieval_lab.json'); if (!response.ok) throw new Error('Retrieval data could not be loaded.'); state.data = await response.json(); state.index = new Map(state.data.vocabulary.map((term, index) => [term, index])); buildHeroLab(); initialiseChunkLab(); runLegacy(); document.querySelectorAll('input[name="chunking"]').forEach((input) => input.addEventListener('change', () => { state.chunking = input.value; runLegacy(); renderHeroResults(); })); document.querySelectorAll('.concept-tab').forEach((button) => button.addEventListener('click', () => { document.querySelectorAll('.concept-tab').forEach((tab) => tab.classList.toggle('is-active', tab === button)); renderConcept(button.dataset.concept); })); renderConcept('tfidf'); } catch (error) { console.error(error); } const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches; const sections = document.querySelectorAll('.reveal'); if (reduce) sections.forEach((section) => section.classList.add('is-visible')); else { const observer = new IntersectionObserver((entries) => entries.forEach((entry) => { if (entry.isIntersecting) { entry.target.classList.add('is-visible'); observer.unobserve(entry.target); } }), { threshold: .12 }); sections.forEach((section) => observer.observe(section)); } $('.menu-toggle').addEventListener('click', () => { const open = $('#site-nav').classList.toggle('is-open'); $('.menu-toggle').setAttribute('aria-expanded', String(open)); }); }
initialise();